INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4072419',1959,69,'P2','Contabilidade Geral - Conceito, Objeto, Finalidade, Técnicas Contábeis, Equação Patrimonial','COGEPS UNIOESTE - Cont (Pref Ivaté)/Pref Ivaté/2026','Caderno Contabilidade Geral Parte 1','A respeito dos fundamentos conceituais da Contabilidade, considerando seu conceito, objeto, finalidade e usuários da informação contábil, analise as afirmações a seguir: I. A Contabilidade é classificada como ciência social aplicada, pois estuda fenômenos patrimoniais que decorrem de decisões humanas e de relações econômicas e jurídicas estabelecidas no âmbito das entidades. II. O objeto da Contabilidade é o patrimônio das entidades, entendido como o conjunto de bens, direitos e obrigações, sendo os resultados econômicos apenas uma consequência da sua variação ao longo do tempo. III. A finalidade da Contabilidade consiste em fornecer informações úteis para a tomada de decisões econômicas, financeiras e patrimoniais, atendendo simultaneamente às necessidades de usuários internos e externos. IV. Os usuários externos da informação contábil restringem-se aos órgãos governamentais e às entidades fiscalizadoras, uma vez que apenas esses possuem interesse direto nas demonstrações contábeis. Está correto o que se afirma em:','[["A","I, II e III, apenas."],["B","I e III, apenas."],["C","II e IV, apenas."],["D","I, II, III e IV."]]'::jsonb,'A',2026,1,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Conceito, Objeto, Finalidade, Técnicas Contábeis, Equação Patrimonial.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é A."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"A — I, II e III, apenas.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Conceito, Objeto, Finalidade, Técnicas Contábeis, Equação Patrimonial"}'::jsonb,'A respeito dos fundamentos conceituais da Contabilidade, considerando seu conceito, objeto, finalidade e usuários da informação contábil, analise as afirmações a seguir: I. A Contabilidade é classificada como ciência social aplicada, pois estuda fenômenos patrimoniais que deco...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4066836',1960,69,'P2','Contabilidade Geral - Conceito, Objeto, Finalidade, Técnicas Contábeis, Equação Patrimonial','FUNDATEC - Teso (Pref Bento Gonçalves)/Pref Bento Gonçalves/2026','Caderno Contabilidade Geral Parte 1','No âmbito da contabilidade, receitas e despesas são elementos fundamentais para a apuração do resultado do exercício. Sobre o tema, assinale a alternativa correta.','[["A","As receitas representam aumentos no patrimônio líquido decorrentes de aportes dos sócios ou proprietários."],["B","As despesas correspondem a reduções no patrimônio líquido, exceto aquelas relacionadas à distribuição de lucros."],["C","As receitas são reconhecidas apenas quando ocorre o recebimento em dinheiro."],["D","As despesas somente são reconhecidas quando efetivamente pagas."],["E","Receitas e despesas não influenciam o patrimônio líquido da entidade."]]'::jsonb,'B',2026,2,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Conceito, Objeto, Finalidade, Técnicas Contábeis, Equação Patrimonial.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — As despesas correspondem a reduções no patrimônio líquido, exceto aquelas relacionadas à distribuição de lucros.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Conceito, Objeto, Finalidade, Técnicas Contábeis, Equação Patrimonial"}'::jsonb,'No âmbito da contabilidade, receitas e despesas são elementos fundamentais para a apuração do resultado do exercício. Sobre o tema, assinale a alternativa correta.') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
