INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4119666',1965,69,'P2','Contabilidade Geral - Princípios Contábeis','Instituto CONSULPAM - Lanç (Pref Pindorama)/Pref Pindorama/2026','Caderno Contabilidade Geral Parte 1','O princípio da prudência impõe a adoção do menor valor para os componentes do ativo e do maior para os do passivo sempre que existirem alternativas igualmente válidas para quantificar mutações patrimoniais. Diante do exposto, é CORRETO afirmar que esse princípio:','[["A","Opta pelo menor valor para ativos e maior para passivos sempre."],["B","Escolhe sempre o maior valor para todos os ativos contábeis registrados."],["C","Considera a avaliação dos ativos pelo valor de mercado mais alto."],["D","Permite aumentar o resultado mediante registros otimistas de avaliação patrimonial extraordinária."]]'::jsonb,'A',2026,17,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Princípios Contábeis.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é A."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"A — Opta pelo menor valor para ativos e maior para passivos sempre.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Princípios Contábeis"}'::jsonb,'O princípio da prudência impõe a adoção do menor valor para os componentes do ativo e do maior para os do passivo sempre que existirem alternativas igualmente válidas para quantificar mutações patrimoniais. Diante do exposto, é CORRETO afirmar que esse princípio:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3963967',1966,69,'P2','Contabilidade Geral - Princípios Contábeis','AVANÇASP - Esc (Pref Nova Odessa)/Pref Nova Odessa/2026','Caderno Contabilidade Geral Parte 1','O princípio contábil que exige que os registros contábeis sejam feitos no momento certo, de forma completa e sem omissões, refletindo a realidade dos fatos, visando à integridade e à tempestividade das informações contábeis, refere-se ao Princípio da:','[["A","Eficiência."],["B","Publicidade."],["C","Oportunidade."],["D","Prudência."],["E","Entidade."]]'::jsonb,'C',2026,18,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Princípios Contábeis.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — Oportunidade.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Princípios Contábeis"}'::jsonb,'O princípio contábil que exige que os registros contábeis sejam feitos no momento certo, de forma completa e sem omissões, refletindo a realidade dos fatos, visando à integridade e à tempestividade das informações contábeis, refere-se ao Princípio da:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4045222',1967,69,'P2','Contabilidade Geral - Princípios Contábeis','Instituto AVALIA - Ana Trans (DETRAN RN)/DETRAN RN/Contabilidade/2026','Caderno Contabilidade Geral Parte 1','Os princípios de contabilidade constituem o alicerce sobre o qual se assenta a doutrina contábil, orientando o registro, a mensuração e a evidenciação dos fenômenos patrimoniais. Com base nesses princípios, analise as assertivas e assinale a alternativa que aponta a(s) correta(s). I. Pelo princípio da prudência, diante de situações de incerteza na avaliação dos elementos patrimoniais, deve-se adotar a alternativa que resulte no menor valor para o patrimônio líquido, evitando a superavaliação de ativos e a subavaliação de passivos. II. O princípio da competência determina que o desgaste dos bens do ativo imobilizado em razão do uso seja reconhecido como despesa apenas no momento da baixa do ativo, quando efetivamente ocorre a perda do investimento. III. O princípio da oportunidade estabelece que os eventos econômicos devem ser reconhecidos e registrados de forma tempestiva, ou seja, quando ocorrem, a fim de gerar informação a tempo para tomada de decisão.','[["A","II e III, apenas."],["B","I e II, apenas."],["C","I e III, apenas."],["D","III, apenas."],["E","I, II e III."]]'::jsonb,'C',2026,19,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Princípios Contábeis.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — I e III, apenas.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Princípios Contábeis"}'::jsonb,'Os princípios de contabilidade constituem o alicerce sobre o qual se assenta a doutrina contábil, orientando o registro, a mensuração e a evidenciação dos fenômenos patrimoniais. Com base nesses princípios, analise as assertivas e assinale a alternativa que aponta a(s) correta...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3963931',1968,69,'P2','Contabilidade Geral - Princípios Contábeis','AVANÇASP - Esc (Pref Nova Odessa)/Pref Nova Odessa/2026','Caderno Contabilidade Geral Parte 1','De acordo com os Princípios Fundamentais de Contabilidade, assinale a alternativa que apresenta corretamente um desses princípios:','[["A","Princípio da Supremacia do Interesse Administrativo."],["B","Princípio da Prudência."],["C","Princípio da Hierarquia Institucional."],["D","Princípio da Centralização Financeira."],["E","Princípio da Subordinação Orçamentária."]]'::jsonb,'B',2026,20,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Princípios Contábeis.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — Princípio da Prudência.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Princípios Contábeis"}'::jsonb,'De acordo com os Princípios Fundamentais de Contabilidade, assinale a alternativa que apresenta corretamente um desses princípios:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.