INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4119662',1969,69,'P2','Contabilidade Geral - Princípios Contábeis','Instituto CONSULPAM - Lanç (Pref Pindorama)/Pref Pindorama/2026','Caderno Contabilidade Geral Parte 1','O princípio do registro pelo valor original estabelece que os componentes do patrimônio sejam registrados pelos valores originais das transações, expressos em moeda nacional. Diante do exposto, assinale a alternativa CORRETA.','[["A","Os ativos são avaliados constantemente pelo valor de mercado atual corrente."],["B","As obrigações devem ser contabilizadas pelo valor justo futuro estimado, sempre."],["C","Os bens devem ser registrados pelo custo de aquisição histórico original."],["D","Os componentes patrimoniais não podem ser reavaliados posteriormente em hipótese alguma."]]'::jsonb,'C',2026,21,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Princípios Contábeis.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — Os bens devem ser registrados pelo custo de aquisição histórico original.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Princípios Contábeis"}'::jsonb,'O princípio do registro pelo valor original estabelece que os componentes do patrimônio sejam registrados pelos valores originais das transações, expressos em moeda nacional. Diante do exposto, assinale a alternativa CORRETA.') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4076214',1970,69,'P2','Contabilidade Geral - Estrutura Conceitual Básica da Contabilidade (CPC 00)','FGV - Ana (TJ SC)/TJ SC/Contábil-Econômico/2026','Caderno Contabilidade Geral Parte 1','Uma entidade vende matéria-prima a terceiros. Em 01/03/2026, um cliente mostrou interesse em realizar uma grande encomenda com pagamento previsto para 120 dias. Em 31/03/2026, as demonstrações contábeis do cliente foram publicadas. Após analisar o Balanço Patrimonial, a entidade decidiu não aceitar a encomenda. Com base no Pronunciamento Técnico CPC 00 (R2) – Estrutura Conceitual para Relatório Financeiro, a informação recebida','[["A","é relevante, uma vez que teve valor confirmatório da situação."],["B","é relevante, uma vez que fez diferença na decisão tomada pela entidade."],["C","não é relevante, uma vez que não teve valor preditivo."],["D","não é relevante, uma vez que a entidade não terá um relacionamento com o cliente."],["E","não é relevante, uma vez que a entidade poderia ter conhecimento sobre a situação a partir de outras fontes."]]'::jsonb,'B',2026,30,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Estrutura Conceitual Básica da Contabilidade (CPC 00).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — é relevante, uma vez que fez diferença na decisão tomada pela entidade.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Estrutura Conceitual Básica da Contabilidade (CPC 00)"}'::jsonb,'Uma entidade vende matéria-prima a terceiros. Em 01/03/2026, um cliente mostrou interesse em realizar uma grande encomenda com pagamento previsto para 120 dias. Em 31/03/2026, as demonstrações contábeis do cliente foram publicadas. Após analisar o Balanço Patrimonial, a entida...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4045231',1971,69,'P2','Contabilidade Geral - Estrutura Conceitual Básica da Contabilidade (CPC 00)','Instituto AVALIA - Ana Trans (DETRAN RN)/DETRAN RN/Contabilidade/2026','Caderno Contabilidade Geral Parte 1','De acordo com a NBC TG – Estrutura Conceitual para Relatório Financeiro, emitida pelo Conselho Federal de Contabilidade, o objetivo primordial do relatório financeiro de propósito geral é fornecer informações financeiras a respeito da entidade reportante que sejam capazes de auxiliar na tomada de decisões relacionadas à alocação de recursos por parte de determinados usuários. Considerando o disposto na referida norma, esses usuários são','[["A","os órgãos de controle interno e externo, com vistas à fiscalização da legalidade e à aplicação de sanções administrativas."],["B","os investidores, os credores por empréstimos e os demais credores, existentes ou potenciais, no que se refere à oferta de recursos à entidade."],["C","as agências de classificação de risco, para fins de análise da capacidade de pagamento e da credibilidade da entidade no mercado."],["D","a administração fazendária, com a finalidade de verificar o cumprimento das obrigações tributárias e apurar eventuais inconsistências fiscais."],["E","os órgãos de defesa do consumidor, para avaliar a conformidade das práticas comerciais e contratuais da entidade."]]'::jsonb,'B',2026,31,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Estrutura Conceitual Básica da Contabilidade (CPC 00).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — os investidores, os credores por empréstimos e os demais credores, existentes ou potenciais, no que se refere à oferta de recursos à entidade.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Estrutura Conceitual Básica da Contabilidade (CPC 00)"}'::jsonb,'De acordo com a NBC TG – Estrutura Conceitual para Relatório Financeiro, emitida pelo Conselho Federal de Contabilidade, o objetivo primordial do relatório financeiro de propósito geral é fornecer informações financeiras a respeito da entidade reportante que sejam capazes de a...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4066490',1972,69,'P2','Contabilidade Geral - Estrutura Conceitual Básica da Contabilidade (CPC 00)','FUNDATEC - TCont (Pref São Martinho RS)/Pref São Martinho RS/2026','Caderno Contabilidade Geral Parte 1','O custo das mercadorias vendidas corresponde ao valor das mercadorias efetivamente ___________ durante o período. Já o inventário físico destina-se à verificação quantitativa e qualitativa dos _____________ da entidade. Assinale a alternativa que preenche, correta e respectivamente, as lacunas do trecho acima.','[["A","adquiridas – passivos"],["B","estocadas – créditos"],["C","vendidas – estoques"],["D","registradas – ativos intangíveis"]]'::jsonb,'C',2026,32,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Estrutura Conceitual Básica da Contabilidade (CPC 00).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — vendidas – estoques","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Estrutura Conceitual Básica da Contabilidade (CPC 00)"}'::jsonb,'O custo das mercadorias vendidas corresponde ao valor das mercadorias efetivamente ___________ durante o período. Já o inventário físico destina-se à verificação quantitativa e qualitativa dos _____________ da entidade. Assinale a alternativa que preenche, correta e respectiva...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4098309',1973,69,'P2','Contabilidade Geral - Estrutura Conceitual Básica da Contabilidade (CPC 00)','IBAM - AFTM (Pref São Vicente)/Pref São Vicente/Análise de Dados/2026','Caderno Contabilidade Geral Parte 1','Assinale a alternativa incorreta.','[["A","O ativo circulante inclui as disponibilidades, os direitos realizáveis no curso do exercício social subsequente e as aplicações de recursos em despesas do exercício seguinte, enquanto o ativo realizável a longo prazo abrange os direitos realizáveis após o término do exercício seguinte."],["B","No ativo, as contas são dispostas em ordem decrescente de grau de liquidez, sendo agrupadas em ativo circulante e ativo não circulante, este último composto por ativo realizável a longo prazo, investimentos, imobilizado e intangível."],["C","As obrigações da companhia, incluindo financiamentos para aquisição de direitos do ativo não circulante, serão classificadas no passivo circulante quando se vencerem no exercício seguinte, e no passivo não circulante se tiverem vencimento em prazo maior, sem qualquer exceção relacionada ao ciclo operacional."],["D","No ativo imobilizado, são classificados os direitos que tenham por objeto bens corpóreos destinados à manutenção das atividades da companhia, inclusive os decorrentes de operações que transfiram à companhia os benefícios, riscos e controle desses bens"]]'::jsonb,'C',2026,33,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Estrutura Conceitual Básica da Contabilidade (CPC 00).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — As obrigações da companhia, incluindo financiamentos para aquisição de direitos do ativo não circulante, serão classificadas no passivo circulante quando se vencerem no exercício seguinte, e no passivo não circulante se tiverem vencimento em prazo maior, sem qualquer exceção relacionada ao ciclo operacional.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Estrutura Conceitual Básica da Contabilidade (CPC 00)"}'::jsonb,'Assinale a alternativa incorreta.') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4108109',1974,69,'P2','Contabilidade Geral - Estrutura Conceitual Básica da Contabilidade (CPC 00)','Legalle - CI (Pref Rolador)/Pref Rolador/2026','Caderno Contabilidade Geral Parte 1','Com base na Estrutura Conceitual da Contabilidade, analise as assertivas abaixo e julgue-as em Verdadeiras (V) ou Falsas (F): ( ) Os relatórios financeiros de proposito geral têm por objetivo evidenciar o valor econômico da entidade que reporta. ( ) A informação financeira é considerada útil quando possui capacidade de influenciar decisões, seja por seu valor preditivo, confirmatório ou ambos. ( ) A comparabilidade das informaçôes financeiras é aprimorada quando eventos ou fenômenos distintos são apresentados de forma similar. Qual alternativa preenche, CORRETAMENTE, de cima para baixo, os parênteses acima?','[["A","F-V-F."],["B","F-V-V"],["C","v-F-v"],["D","V-V-F"]]'::jsonb,'A',2026,34,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Estrutura Conceitual Básica da Contabilidade (CPC 00).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é A."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"A — F-V-F.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Estrutura Conceitual Básica da Contabilidade (CPC 00)"}'::jsonb,'Com base na Estrutura Conceitual da Contabilidade, analise as assertivas abaixo e julgue-as em Verdadeiras (V) ou Falsas (F): ( ) Os relatórios financeiros de proposito geral têm por objetivo evidenciar o valor econômico da entidade que reporta. ( ) A informação financeira é c...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3991068',1975,83,'P1','Contabilidade Geral - Escrituração: Normas, Livros Contábeis, Lançamentos, Método das Partidas Dobradas','Instituto ACCESS - Tec (UFFS)/UFFS/Contabilidade/2026','Caderno Contabilidade Geral Parte 1','O método das partidas dobradas é o pilar da contabilidade moderna, garantindo que o equilíbrio patrimonial seja mantido em cada lançamento efetuado. Considerando os princípios matemáticos e lógicos desse método de escrituração, analise as afirmativas a segui. I.Para cada lançamento a débito em uma ou mais contas, deve existir um lançamento a crédito de igual valor em uma ou mais contas. II.A soma dos saldos devedores de todas as contas da entidade deve ser sempre igual à soma dos saldos credores ao final de cada período. III.O método das partidas dobradas permite que um único fato contábil seja registrado apenas como um crédito, dispensando o débito correspondente. Está correto o que se afirma em:','[["A","I e III apenas."],["B","I e II apenas."],["C","I, II e III."],["D","II apenas."],["E","III apenas."]]'::jsonb,'B',2026,67,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Escrituração: Normas, Livros Contábeis, Lançamentos, Método das Partidas Dobradas.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — I e II apenas.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Escrituração: Normas, Livros Contábeis, Lançamentos, Método das Partidas Dobradas"}'::jsonb,'O método das partidas dobradas é o pilar da contabilidade moderna, garantindo que o equilíbrio patrimonial seja mantido em cada lançamento efetuado. Considerando os princípios matemáticos e lógicos desse método de escrituração, analise as afirmativas a segui. I.Para cada lança...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4063564',1976,83,'P1','Contabilidade Geral - Escrituração: Normas, Livros Contábeis, Lançamentos, Método das Partidas Dobradas','FUNDATEC - Cont (Pref São Martinho RS)/Pref São Martinho RS/2026','Caderno Contabilidade Geral Parte 1','Na escrituração contábil pelo método das partidas dobradas, todo débito lançado em uma conta corresponde a um ou mais ___________ de igual valor total em outra conta. Já os fatos que alteram a composição patrimonial sem modificar o patrimônio líquido são denominados fatos _____________. Assinale a alternativa que preenche, correta e respectivamente, as lacunas do trecho acima.','[["A","créditos – modificativos"],["B","saldos – permutativos"],["C","créditos – permutativos"],["D","saldos – mistos"]]'::jsonb,'C',2026,68,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Escrituração: Normas, Livros Contábeis, Lançamentos, Método das Partidas Dobradas.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — créditos – permutativos","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Escrituração: Normas, Livros Contábeis, Lançamentos, Método das Partidas Dobradas"}'::jsonb,'Na escrituração contábil pelo método das partidas dobradas, todo débito lançado em uma conta corresponde a um ou mais ___________ de igual valor total 