INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3992084',1977,83,'P1','Contabilidade Geral - Escrituração: Normas, Livros Contábeis, Lançamentos, Método das Partidas Dobradas','FGV - Bach (CFC)/CFC/1º Exame de Suficiência/2026','Caderno Contabilidade Geral Parte 1','Ao preparar o encerramento do exercício, o setor de Contabilidade da companhia “B” S.A. listou as seguintes contas e seus respectivos saldos: 1. Adiantamento a fornecedor: R$ 12.000,00; 2. Adiantamento de clientes: R$ 8.000,00; 3. Encargos financeiros a transcorrer (sobre empréstimos bancários obtidos): R$ 3.500,00; 4. Ações de emissão própria em tesouraria: R$ 5.000,00; 5. Juros sobre o capital próprio a pagar: R$ 4.500,00; 6. Perdas estimadas com créditos de liquidação duvidosa: R$ 2.000,00. Assinale a opção que indica o somatório correto, em valores absolutos, das contas de natureza devedora.','[["A","R$ 20.500,00."],["B","R$ 15.500,00."],["C","R$ 12.000,00."],["D","R$ 20.000,00."]]'::jsonb,'A',2026,69,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Escrituração: Normas, Livros Contábeis, Lançamentos, Método das Partidas Dobradas.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é A."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"A — R$ 20.500,00.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Escrituração: Normas, Livros Contábeis, Lançamentos, Método das Partidas Dobradas"}'::jsonb,'Ao preparar o encerramento do exercício, o setor de Contabilidade da companhia “B” S.A. listou as seguintes contas e seus respectivos saldos: 1. Adiantamento a fornecedor: R$ 12.000,00; 2. Adiantamento de clientes: R$ 8.000,00; 3. Encargos financeiros a transcorrer (sobre empr...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3999847',1978,83,'P1','Contabilidade Geral - Escrituração: Normas, Livros Contábeis, Lançamentos, Método das Partidas Dobradas','DIRENS Aeronáutica - EAGS (EEAR)/EEAR/Administração/2026','Caderno Contabilidade Geral Parte 1','Assinale a alternativa que sob o ponto de vista contábil é o mais importante dos livros utilizados pela Contabilidade. Por meio dele é possível controlar, separadamente, o movimento de todas as contas.','[["A","Livro Contas-Correntes"],["B","Livro Razão"],["C","Livro Caixa"],["D","Livro Diário"]]'::jsonb,'B',2026,70,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Escrituração: Normas, Livros Contábeis, Lançamentos, Método das Partidas Dobradas.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — Livro Razão","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Escrituração: Normas, Livros Contábeis, Lançamentos, Método das Partidas Dobradas"}'::jsonb,'Assinale a alternativa que sob o ponto de vista contábil é o mais importante dos livros utilizados pela Contabilidade. Por meio dele é possível controlar, separadamente, o movimento de todas as contas.') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3986877',1979,83,'P1','Contabilidade Geral - Escrituração: Normas, Livros Contábeis, Lançamentos, Método das Partidas Dobradas','FUNDATEC - Tec Inf (Pref Bom Jesus (RS))/Pref Bom Jesus (RS)/Contabilidade/2026','Caderno Contabilidade Geral Parte 1','No processo de escrituração contábil, uma entidade registrou uma operação de pagamento de fornecedor anteriormente reconhecida como obrigação. Considerando os princípios e a técnica contábil, assinale a alternativa correta.','[["A","O pagamento de fornecedor implica débito em despesa e crédito em caixa, pois representa saída de recursos financeiros."],["B","O pagamento de fornecedor implica débito no passivo e crédito no ativo, sem impacto no resultado do exercício."],["C","O pagamento de fornecedor implica débito no ativo e crédito no passivo, reduzindo o patrimônio líquido."],["D","O pagamento de fornecedor deve ser registrado apenas no controle financeiro, não sendo necessário lançamento contábil."]]'::jsonb,'B',2026,71,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Escrituração: Normas, Livros Contábeis, Lançamentos, Método das Partidas Dobradas.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — O pagamento de fornecedor implica débito no passivo e crédito no ativo, sem impacto no resultado do exercício.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Escrituração: Normas, Livros Contábeis, Lançamentos, Método das Partidas Dobradas"}'::jsonb,'No processo de escrituração contábil, uma entidade registrou uma operação de pagamento de fornecedor anteriormente reconhecida como obrigação. Considerando os princípios e a técnica contábil, assinale a alternativa correta.') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4066837',1980,83,'P1','Contabilidade Geral - Escrituração: Normas, Livros Contábeis, Lançamentos, Método das Partidas Dobradas','FUNDATEC - Teso (Pref Bento Gonçalves)/Pref Bento Gonçalves/2026','Caderno Contabilidade Geral Parte 1','Com base nos princípios da contabilidade, analise as assertivas a seguir: I. A escrituração contábil deve registrar, em ordem cronológica, todos os fatos administrativos que provoquem alterações no patrimônio da entidade. II. A escrituração dos fatos contábeis deve observar o método das partidas dobradas, no qual todo débito corresponde a um ou mais créditos de igual valor. III. Somente os fatos que envolvem entrada ou saída de dinheiro devem ser registrados na contabilidade. Quais estão corretas?','[["A","Apenas I."],["B","Apenas I e II."],["C","Apenas I e III."],["D","Apenas II e III."],["E","I, II e III."]]'::jsonb,'B',2026,72,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Escrituração: Normas, Livros Contábeis, Lançamentos, Método das Partidas Dobradas.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — Apenas I e II.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Escrituração: Normas, Livros Contábeis, Lançamentos, Método das Partidas Dobradas"}'::jsonb,'Com base nos princípios da contabilidade, analise as assertivas a seguir: I. A escrituração contábil deve registrar, em ordem cronológica, todos os fatos administrativos que provoquem alterações no patrimônio da entidade. II. A escrituração dos fatos contábeis deve observar o ...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4066774',1981,83,'P1','Contabilidade Geral - Escrituração: Normas, Livros Contábeis, Lançamentos, Método das Partidas Dobradas','FUNDATEC - Tec (Bto Gonçalves)/Pref Bento Gonçalves/Contabilidade/2026','Caderno Contabilidade Geral Parte 1','Com base na ITG 2000 (R1) – Escrituração Contábil, analise as assertivas abaixo e assinale a alternativa correta. I. A escrituração contábil deve ser feita em língua portuguesa e em moeda corrente nacional, observando-se a forma contábil, a ordem cronológica de dia, mês e ano, sem espaços em branco, entrelinhas, borrões, rasuras ou emendas. II. A escrituração contábil deve registrar os atos e fatos administrativos que provoquem ou possam vir a provocar alterações no patrimônio da entidade. III. A escrituração contábil deve ser realizada com base em documentos de origem interna ou externa, idôneos, que comprovem os atos e fatos administrativos. Quais estão corretas?','[["A","Todas as assertivas estão corretas."],["B","Todas as assertivas estão incorretas."],["C","Apenas a assertiva III está correta."],["D","Apenas as assertivas I e II estão corretas."],["E","Apenas as assertivas II e III estão corretas."]]'::jsonb,'A',2026,73,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Escrituração: Normas, Livros Contábeis, Lançamentos, Método das Partidas Dobradas.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é A."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"A — Todas as assertivas estão corretas.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Escrituração: Normas, Livros Contábeis, Lançamentos, Método das Partidas Dobradas"}'::jsonb,'Com base na ITG 2000 (R1) – Escrituração Contábil, analise as assertivas abaixo e assinale a alternativa correta. I. A escrituração contábil deve ser feita em língua portuguesa e em moeda corrente nacional, observando-se a forma contábil, a ordem cronológica de dia, mês e ano,...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
